import FullCalendar, { EventDropArg } from '@fullcalendar/react';
import dayGridPlugin from '@fullcalendar/daygrid';
import interactionPlugin from '@fullcalendar/interaction';
import timeGridPlugin from '@fullcalendar/timegrid';
import listPlugin from '@fullcalendar/list';
import BootstrapTheme from '@fullcalendar/bootstrap';
import { EventInput } from '@fullcalendar/core';
import { Col } from 'react-bootstrap';
import './calendar.css';
import { showMessage } from '../../utils/AllFunction';

const Calendar = ({ onDateClick, onEventClick, onDrop, onEventDrop, events, Title }) => {

    const disabledDates = events.map(event => new Date(event.start).toISOString().split('T')[0]);

    const handleDateClick = (arg) => {
        const eventDate = arg.dateStr;
        if (disabledDates.includes(eventDate)) {
            return;
        }
        onDateClick(arg);
    };


    return (
        <>
            {/* full calendar control */}
            <Col md={4}>
                <h4 style={{ lineHeight: '100%' }}>
                    {' '}
                    {Title}
                </h4>
            </Col>
            <div id="calendar" className="calendar-wrapper mt-2">
                <FullCalendar
                    initialView="dayGridMonth"
                    plugins={[dayGridPlugin, interactionPlugin, timeGridPlugin, listPlugin, BootstrapTheme]}
                    handleWindowResize={true}
                    themeSystem="bootstrap"
                    buttonText={{
                        today: 'Today',
                        // month: 'Month',
                        // week: 'Week',
                        // day: 'Day',
                        // list: 'List',
                        prev: '<',
                        next: '>',
                    }}
                    headerToolbar={{
                        left: 'prev',
                        center: 'title',
                        right: 'next today',
                        // right: 'prev,dayGridMonth,timeGridWeek,timeGridDay,listMonth',
                    }}
                    editable={false}
                    selectable={true}
                    droppable={false}
                    events={events}
                    eventDidMount={(info) => {
                        info.el.setAttribute('title', info.event.title);
                    }}
                    // dateClick={handleDateClick}
                    displayEventTime={false}
                    height={"auto"}
                    // drop={handleDrop}
                    // eventDrop={handleEventDrop}

                    dateClick={(arg) => {
                        const clickedDate = new Date(arg.date);
                        if (clickedDate.getDay() === 0) {
                            // 0 = Sunday
                            showMessage('error', "No attendance is required on Sundays, as it is a holiday.");
                            return;
                        }
                        handleDateClick(arg);
                    }}

                    // Grey out Sundays
                    dayCellDidMount={(info) => {
                        const date = new Date(info.date);
                        if (date.getDay() === 0) {
                            info.el.style.backgroundColor = "#ccc"; // light red
                            info.el.style.pointerEvents = "none"; // disable click
                            info.el.style.opacity = "0.6";
                        }
                    }}
                />
            </div>

        </>
    );
};

export default Calendar;
