import React, { useEffect, useRef, useState } from 'react';
import { Badge, Button, Card, Col, Form, Row, Spinner, OverlayTrigger, Tooltip,Alert } from 'react-bootstrap';
import ModelViewBox from '../../components/Atom/ModelViewBox';
import FormLayout from '../../utils/formLayout';
import Table from '../../components/Table';
import { findArrObj, formatDate, showConfirmationDialog, showMessage } from '../../utils/AllFunction';
import {
    resetGetHoliday,
    getHolidayRequest,
    getDepartmentRequest,
    resetGetDepartment,
    resetGetBranch,
    getBranchRequest,
    resetGetStaff,
    getStaffRequest,
    resetGetStaffLeave,
    getStaffLeaveRequest,
} from '../../redux/actions';
import { usePageTitle, useRedux } from '../../hooks';
import { NotificationContainer } from 'react-notifications';
import Calendar from '../../components/Atom/Calendar';
import _ from 'lodash';
import {
    createStaffAttendanceRequest,
    getStaffAttendanceRequest,
    resetCreateStaffAttendance,
    resetGetStaffAttendance,
    resetUpdateStaffAttendance,
    updateStaffAttendanceRequest,
} from '../../redux/staff-attendance/actions';
import moment from 'moment';
import { FaCheckCircle, FaTimesCircle, FaAdjust, FaUmbrellaBeach, FaSun, FaMinus, FaBan } from 'react-icons/fa';
import { baseURL } from '../../api/ApiConfig';
import noProfile from '../../assets/images/noprofile_images.jpg';
import CardViewBox from '../../components/Atom/CardViewBox';

let parentList = [];
let isShowBtn = true;
let modelHead = false;
function Index() {
    usePageTitle({
        title: 'Staff Attendance',
        breadCrumbItems: [
            {
                path: '/attendance/staff-attendance',
                label: 'Attendance',
            },
            {
                path: '/attendance/staff-attendance',
                label: 'Staff Attendance Entry',
                active: true,
            },
        ],
    });

    const { dispatch, appSelector } = useRedux();
    const loginInfo = localStorage.getItem('loginInfo');
    const localData = JSON.parse(loginInfo);
    const pageAccessData = findArrObj(localData?.[0]?.pagePermission, 'label', "Staff Attendance");
    const accessIds = (pageAccessData?.[0]?.access || '').split(',').map(id => id.trim()); // for access create and update and delete actions ['1', '2', '3', '4', '5', '6']
    const branchIdforRole = localData?.[0]?.branchId; // for branch list can only show
    const roleIdforRole = localData?.[0]?.roleId; // for role Permission (1.superadmin)
    const staffViewFlag = localData?.[0]?.staffViewFlag;
    const staffId = localData?.[0]?.staffId;
    const canSeeAllBranches = roleIdforRole == 1 || _.includes(accessIds, '3') || _.includes(accessIds, '8');

    const {
        getStaffSuccess,
        getStaffList,
        getStaffFailure,
        getHolidaySuccess,
        getHolidayList,
        getHolidayFailure,
        errorMessage,
        getDepartmentSuccess,
        getDepartmentList,
        getDepartmentFailure,
        getBranchSuccess,
        getBranchList,
        getBranchFailure,
        createStaffAttendanceSuccess,
        createStaffAttendanceFailure,
        createStaffAttendanceData,
        getStaffLeaveSuccess,
        getStaffLeaveList,
        getStaffLeaveFailure,
        getStaffAttendanceSuccess,
        getStaffAttendanceList,
        getStaffAttendanceFailure,
        updateStaffAttendanceSuccess,
        updateStaffAttendanceFailure,
        updateStaffAttendanceData
    } = appSelector((state) => ({
        getStaffLeaveSuccess: state.staffLeaveReducer.getStaffLeaveSuccess,
        getStaffLeaveList: state.staffLeaveReducer.getStaffLeaveList,
        getStaffLeaveFailure: state.staffLeaveReducer.getStaffLeaveFailure,

        getHolidaySuccess: state.holidayReducer.getHolidaySuccess,
        getHolidayList: state.holidayReducer.getHolidayList,
        getHolidayFailure: state.holidayReducer.getHolidayFailure,

        getStaffAttendanceSuccess: state.staffAttendanceReducer.getStaffAttendanceSuccess,
        getStaffAttendanceList: state.staffAttendanceReducer.getStaffAttendanceList,
        getStaffAttendanceFailure: state.staffAttendanceReducer.getStaffAttendanceFailure,

        createStaffAttendanceSuccess: state.staffAttendanceReducer.createStaffAttendanceSuccess,
        createStaffAttendanceData: state.staffAttendanceReducer.createStaffAttendanceData,
        createStaffAttendanceFailure: state.staffAttendanceReducer.createStaffAttendanceFailure,

        updateStaffAttendanceSuccess: state.staffAttendanceReducer.updateStaffAttendanceSuccess,
        updateStaffAttendanceData: state.staffAttendanceReducer.updateStaffAttendanceData,
        updateStaffAttendanceFailure: state.staffAttendanceReducer.updateStaffAttendanceFailure,

        getDepartmentSuccess: state.departmentReducer.getDepartmentSuccess,
        getDepartmentList: state.departmentReducer.getDepartmentList,
        getDepartmentFailure: state.departmentReducer.getDepartmentFailure,

        getBranchSuccess: state.branchReducer.getBranchSuccess,
        getBranchList: state.branchReducer.getBranchList,
        getBranchFailure: state.branchReducer.getBranchFailure,

        getStaffSuccess: state.staffReducer.getStaffSuccess,
        getStaffList: state.staffReducer.getStaffList,
        getStaffFailure: state.staffReducer.getStaffFailure,
    }));

    // Add state for approved leaves
    const [approvedLeaveStaffIds, setApprovedLeaveStaffIds] = useState([]);
    const [leaveDetails, setLeaveDetails] = useState({});

    const columns = [
        // {
        //     Header: 'S.No',
        //     accessor: 'id',
        //     Cell: (row) => <div>{row?.row?.index + 1}</div>,
        // },
        {
            Header: 'Employee',
            accessor: 'staffName',
            Cell: ({ row }) => {
                const hasApprovedLeave = approvedLeaveStaffIds.includes(row.original?.staffId);
                
                return (
                    <div className="inbox-item-img me-3" style={{ display: 'flex', alignItems: 'center' }}>
                        <img
                            src={row?.original?.staffProfile ? `${baseURL}${row?.original.staffProfile}` : noProfile}
                            alt="staffProfile"
                            className="rounded-circle"
                            crossOrigin="anonymous"
                            onError={(e) => {
                                e.target.onerror = null;
                                e.target.src = noProfile;
                            }}
                            style={{ width: "50px", height: "50px", objectFit: "cover", marginRight: "10px" }}
                        />
                        <div>
                            <div style={{ fontSize: '15px', fontWeight: '600' }}>
                                {row?.original?.staffName}
                                {hasApprovedLeave && (
                                    <Badge bg="warning" text="dark" className="ms-2">
                                        <FaBan className="me-1" size={12} /> On Leave
                                    </Badge>
                                )}
                            </div>
                            <div style={{ fontSize: '12px', textAlign: 'left', color: '#888' }}>
                                {row?.original?.staffCode}
                            </div>
                        </div>
                    </div>
                );
            }
        },
        {
            Header: 'Status',
            accessor: 'Attendance',
            Cell: ({ row }) => {
                const hasApprovedLeave = approvedLeaveStaffIds.includes(row.original?.staffId);
                const details = leaveDetails[row.original?.staffId];

                return (
                    <Row>
                        <Col lg={4} className="my-1">
                            {hasApprovedLeave ? (
                                <OverlayTrigger
                                    placement="top"
                                    overlay={<Tooltip>Cannot mark Present - Employee has approved leave</Tooltip>}
                                >
                                    <div className="d-flex align-items-center" style={{ opacity: 0.5, cursor: 'not-allowed' }}>
                                        <FaCheckCircle color="#ccc" size={22} />
                                        <span className="ms-2" style={{ color: "#999" }}>Present</span>
                                    </div>
                                </OverlayTrigger>
                            ) : (
                                <div
                                    className={`icon-radio d-flex align-items-center ${state.staffAttendance[row.index]?.attendanceStatusId === 1 ? 'active' : ''}`}
                                    onClick={() => handleChange(row.original, 1, row.index)}
                                    style={{ cursor: 'pointer' }}
                                >
                                    <FaCheckCircle color={state.staffAttendance[row.index]?.attendanceStatusId === 1 ? "#28a745" : "#ccc"} size={22} />
                                    <span className="ms-2" style={{ color: state.staffAttendance[row.index]?.attendanceStatusId === 1 ? "#28a745" : "#000" }}> Present</span>
                                </div>
                            )}
                        </Col>

                        <Col lg={4} className="my-1">
                            <div
                                className={`icon-radio d-flex align-items-center ${state.staffAttendance[row.index]?.attendanceStatusId === 0 ? 'active' : ''}`}
                                onClick={() => handleChange(row.original, 0, row.index)}
                                style={{ cursor: 'pointer' }}
                            >
                                <FaTimesCircle color={state.staffAttendance[row.index]?.attendanceStatusId === 0 ? "#FF0000" : "#ccc"} size={22} />
                                <span className="ms-2" style={{ color: state.staffAttendance[row.index]?.attendanceStatusId === 0 ? "#FF0000" : "#000" }}>Absent</span>
                            </div>
                        </Col>

                        <Col lg={4} className="my-1">
                            {hasApprovedLeave ? (
                                <OverlayTrigger
                                    placement="top"
                                    overlay={<Tooltip>Cannot mark Half Day - Employee has approved leave</Tooltip>}
                                >
                                    <div className="d-flex align-items-center" style={{ opacity: 0.5, cursor: 'not-allowed' }}>
                                        <FaAdjust color="#ccc" size={22} />
                                        <span className="ms-2" style={{ color: "#999" }}>Half Day</span>
                                    </div>
                                </OverlayTrigger>
                            ) : (
                                <div
                                    className={`icon-radio d-flex align-items-center ${state.staffAttendance[row.index]?.attendanceStatusId === 2 ? 'active' : ''}`}
                                    onClick={() => handleChange(row.original, 2, row.index)}
                                    style={{ cursor: 'pointer' }}
                                >
                                    <FaAdjust color={state.staffAttendance[row.index]?.attendanceStatusId === 2 ? "DodgerBlue" : "#ccc"} size={22} />
                                    <span className="ms-2" style={{ color: state.staffAttendance[row.index]?.attendanceStatusId === 2 ? "DodgerBlue" : "#000" }}>Half Day</span>
                                </div>
                            )}
                        </Col>
                    </Row>

                );
            },
        },
    ];


    const [state, setState] = useState({
        attendanceDate: formatDate(new Date()),
        staffAttendance: [{}],
        branchId: branchIdforRole,
        departmentId: 0,
    });

    const [selectedItem, setSelectedItem] = useState({});
    const [selectedIndex, setSelectedIndex] = useState(false);
    const [modal, setModal] = useState(false);
    const [isLoading, setIsLoading] = useState(false);

    const [isMobile, setIsMobile] = useState(window.innerWidth < 768);
    // event data
    const [events, setEvents] = useState([]);


    useEffect(() => {
        setIsLoading(true);
        dispatch(getHolidayRequest());
        
        // Fetch approved leaves for today
        const leaveReq = {
            attendanceDate: moment().format('YYYY-MM-DD'),
            statusId: 29
        };
        dispatch(getStaffLeaveRequest(leaveReq));
        
        let attendanceDate = {
            attendanceDate: moment().format('YYYY-MM-DD'),
            // staffId: staffId,

        };
        if (roleIdforRole != 1) {
            attendanceDate.branchId = branchIdforRole
        }
        // dispatch(getBranchRequest());
        // dispatch(getDepartmentRequest());

        dispatch(getStaffAttendanceRequest(attendanceDate));
    }, []);

    useEffect(() => {
        const handleResize = () => setIsMobile(window.innerWidth < 768);
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    useEffect(() => {
        if (getStaffLeaveSuccess && getStaffLeaveList) {
            // Filter approved leaves that cover the selected date
            const approvedLeaves = getStaffLeaveList.filter(leave => {
                if (leave.statusId !== 29) return false;
                
                const fromDate = moment(leave.fromDate).format('YYYY-MM-DD');
                const toDate = moment(leave.toDate).format('YYYY-MM-DD');
                const selectedDate = state.attendanceDate;
                
                return selectedDate >= fromDate && selectedDate <= toDate;
            });
            
            // Get staff IDs with approved leaves
            const staffIds = approvedLeaves.map(leave => leave.staffId);
            setApprovedLeaveStaffIds(staffIds);
            
            // Store leave details
            const details = {};
            approvedLeaves.forEach(leave => {
                details[leave.staffId] = {
                    leaveType: leave.leaveTypeName,
                    reason: leave.reason,
                    fromDate: leave.fromDate,
                    toDate: leave.toDate
                };
            });
            setLeaveDetails(details);
            
            dispatch(resetGetStaffLeave());
        } else if (getStaffLeaveFailure) {
            dispatch(resetGetStaffLeave());
        }
    }, [getStaffLeaveSuccess, getStaffLeaveFailure, state.attendanceDate]);

    useEffect(() => {
        if (getHolidaySuccess) {
            const eventList = _.map(getHolidayList, (event) => ({
                id: event.holidayId,
                title: event.reason,
                start: new Date(event.holidayDate),
                className: 'bg-danger',
            }));
            setEvents(eventList);
            dispatch(resetGetHoliday());
        } else if (getHolidayFailure) {
            setEvents([]);
            dispatch(resetGetHoliday());
        }
    }, [getHolidaySuccess, getHolidayFailure]);


    useEffect(() => {
        if (getStaffAttendanceSuccess) {
            setIsLoading(false);
            parentList = getStaffAttendanceList;
            setState({
                ...state,
                staffAttendance: getStaffAttendanceList,
            });
            dispatch(resetGetStaffAttendance());
        } else if (getStaffAttendanceFailure) {
            setIsLoading(false);
            dispatch(resetGetStaffAttendance());
        }
    }, [getStaffAttendanceSuccess, getStaffAttendanceFailure]);

    useEffect(() => {
        if (updateStaffAttendanceSuccess) {
            showMessage('success', 'Attendance updated successfully');
            let attendanceDate = {
                attendanceDate: moment().format('YYYY-MM-DD'),
            };
            if (roleIdforRole != 1) {
                attendanceDate.staffId = staffId;
            }
            dispatch(getStaffAttendanceRequest(attendanceDate));
            
            // Refresh leave data
            const leaveReq = {
                attendanceDate: state.attendanceDate,
                statusId: 29
            };
            dispatch(getStaffLeaveRequest(leaveReq));
            
            closeModel();
            dispatch(resetUpdateStaffAttendance());
        } else if (updateStaffAttendanceFailure) {
            showMessage('warning', errorMessage);
            dispatch(resetUpdateStaffAttendance());
        }
    }, [updateStaffAttendanceSuccess, updateStaffAttendanceFailure]);

    useEffect(() => {
        if (!modal) {
            closeModel();
        }
    }, [modal])

    const closeModel = () => {
        setModal(false);
        onFormClear();
        setTimeout(() => {
            parentList = [];
        }, 0)
    };

    const onFormClear = () => {
        setState({
            attendanceDate: formatDate(new Date()),
            staffAttendance: [{}],
            branchId: branchIdforRole,
            departmentId: 0,
        });
    };

    const createModel = () => {
        onFormClear();
        setModal(true);
    };


    const onFormSubmit = async () => {
        // Check if any staff with approved leave is being marked as Present or Half Day
        const invalidMarks = state.staffAttendance.filter(
            item => approvedLeaveStaffIds.includes(item.staffId) && 
            (item.attendanceStatusId === 1 || item.attendanceStatusId === 2)
        );

        if (invalidMarks.length > 0) {
            showMessage('error', 'Cannot mark Present or Half Day for employees on approved leave');
            return;
        }

        const submitRequest = {
            staffAttendance: state?.staffAttendance || '',
        }
        dispatch(updateStaffAttendanceRequest(submitRequest));
    };

    const onDateClick = (arg) => {
        if (arg?.dateStr > formatDate(new Date())) {
            showMessage('error', "Please select a valid date (not in the future).");
            return;
        }

        if (arg?.dateStr == formatDate(new Date())) {
            isShowBtn = true;
            modelHead = false;
        } else {
            isShowBtn = false;
            modelHead = true;
        }
        
        // Fetch leaves for the selected date
        const leaveReq = {
            attendanceDate: arg?.dateStr,
            statusId: 29
        };
        dispatch(getStaffLeaveRequest(leaveReq));
        
        const attendanceDate = {
            attendanceDate: arg?.dateStr || state.attendanceDate,
            branchId: state.branchId || ''
        };
        dispatch(getStaffAttendanceRequest(attendanceDate));

        if (isMobile) {
            createModel();
        }
        setIsLoading(true);
        const updateDate = parentList.map((data) => {
            return {
                ...data,
                attendanceDate: arg?.dateStr || '',
                attendanceInchargeId: 1,
            };
        });
        parentList = updateDate;
        if (roleIdforRole != 1) {
            if (!staffViewFlag) {
                parentList = parentList.filter(item => item.staffId == staffId);
            }
        }
        setState({
            ...state,
            attendanceDate: arg?.dateStr,
            staffAttendance: parentList,
        });
    };

    const handleChange = (staffDetail, statusId, index) => {
        // Prevent marking Present or Half Day for staff on approved leave
        if (approvedLeaveStaffIds.includes(staffDetail.staffId) && (statusId === 1 || statusId === 2)) {
            showMessage('warning', 'Cannot mark Present or Half Day - Employee has approved leave');
            return;
        }

        setState((prev) => {
            const updatedStaffAttendance = [...prev.staffAttendance];

            updatedStaffAttendance[index] = {
                ...updatedStaffAttendance[index],
                staffId: staffDetail.staffId,
                attendanceStatusId: statusId, // 0: Absent, 1: Present, 2: Half-day
            };

            return {
                ...prev,
                staffAttendance: updatedStaffAttendance,
            };
        });
    };

    const handleMarkAll = (statusId) => {
        // Check if trying to mark all as Present/Half Day and there are staff on leave
        if ((statusId === 1 || statusId === 2) && approvedLeaveStaffIds.length > 0) {
            showMessage('error', 'Cannot mark all as Present/Half Day - Some employees have approved leave');
            return;
        }

        setState((prev) => {
            const updatedStaffAttendance = prev.staffAttendance.map((att, index) => ({
                ...att,
                staffId: att.staffId || prev.staffAttendance[index]?.staffId,
                attendanceStatusId: statusId,
            }));

            return {
                ...prev,
                staffAttendance: updatedStaffAttendance,
            };
        });
    };


    return (
        <React.Fragment>
            <NotificationContainer />

            <Card>
                <Card.Body>
                    {/* Show warning if there are employees on leave */}
                    {approvedLeaveStaffIds.length > 0 && (
                        <Alert variant="warning" className="mb-3">
                            <FaBan className="me-2" />
                            <strong>{approvedLeaveStaffIds.length}</strong> employee(s) have approved leave today. 
                            They can only be marked as Absent.
                        </Alert>
                    )}

                    <Row className="">
                        <Col lg={5} md={12} xs={12}>
                            <Calendar
                                onDateClick={(roleIdforRole == 1 || _.some(['1', '2'], id => _.includes(accessIds, id))) && onDateClick}
                                // onEventClick={onEventClick}
                                // onDrop={onDrop}
                                Title={'Staff Attendance'}
                                events={events}
                            // onEventDrop={onEventDrop}
                            />

                            <Card>
                                <Card.Body>
                                    <h4 style={{ marginBottom: '20px', fontWeight: 'bold' }}>Attendance Legend</h4>
                                    <ul style={{ listStyleType: 'none', padding: 0, lineHeight: '2.2' }}>
                                        <li>
                                            <FaCheckCircle color="#28a745" size={18} />{' '}
                                            <strong style={{ fontSize: '18px', color: '#28a745' }}>Present</strong>
                                        </li>
                                        <li>
                                            <FaTimesCircle color="#dc3545" size={18} />{' '}
                                            <strong style={{ fontSize: '18px', color: '#dc3545' }}>Absent</strong>
                                        </li>
                                        <li>
                                            <FaAdjust color="#007bff" size={18} />{' '}
                                            <strong style={{ fontSize: '18px', color: '#007bff' }}>Half Day</strong>
                                        </li>
                                        <li>
                                            <FaUmbrellaBeach color="#9400ff" size={18} />{' '}
                                            <strong style={{ fontSize: '18px', color: '#9400ff' }}>Holiday</strong>
                                        </li>
                                        <li>
                                            <FaSun color="#fd7e14" size={18} />{' '}
                                            <strong style={{ fontSize: '18px', color: '#fd7e14' }}>Sunday</strong>
                                        </li>
                                        <li>
                                            <FaBan color="#ffc107" size={18} />{' '}
                                            <strong style={{ fontSize: '18px', color: '#ffc107' }}>On Leave</strong>
                                        </li>
                                        <li>
                                            <FaMinus color="#6c757d" size={18} />{' '}
                                            <strong style={{ fontSize: '18px', color: '#6c757d' }}>Not Marked</strong>
                                        </li>
                                    </ul>
                                </Card.Body>
                            </Card>
                        </Col>

                        {!isMobile && (
                            <Col lg={7} md={12} xs={12}>
                                {isLoading ? (
                                    <div className="bg-light opacity-0.25">
                                        <div className="d-flex justify-content-center m-5">
                                            <Spinner className="mt-5 mb-5" animation="border" />
                                        </div>
                                    </div>
                                ) : (
                                    <CardViewBox
                                        card={!isMobile}
                                        saveBtn={roleIdforRole == 1 ? true : isShowBtn}
                                        cancelBtn={isShowBtn}
                                        cardHead={false}
                                        isEdit={false}
                                        handleSubmit={onFormSubmit}
                                    >
                                        <Table
                                            columns={columns}
                                            Title="Employee List"
                                            data={parentList || []}
                                            ifComponent={
                                                <div className="d-flex justify-content-end gap-2 my-2">
                                                    <Button 
                                                        variant="success" 
                                                        size="sm" 
                                                        onClick={() => handleMarkAll(1)}
                                                        disabled={approvedLeaveStaffIds.length > 0}
                                                    >
                                                        <FaCheckCircle className="me-1" /> Present
                                                    </Button>
                                                    <Button variant="danger" size="sm" onClick={() => handleMarkAll(0)}>
                                                        <FaTimesCircle className="me-1" /> Absent
                                                    </Button>
                                                    <Button 
                                                        variant="primary" 
                                                        size="sm" 
                                                        onClick={() => handleMarkAll(2)}
                                                        disabled={approvedLeaveStaffIds.length > 0}
                                                    >
                                                        <FaAdjust className="me-1" /> HalfDay
                                                    </Button>
                                                </div>
                                            }
                                            toggle={false}
                                            pagination={false}
                                        />
                                    </CardViewBox>
                                )}
                            </Col>
                        )}
                    </Row>
                </Card.Body>
            </Card>

            {isMobile && (
                <ModelViewBox
                    modal={modal}
                    setModel={setModal}
                    modelHeader={'Attendance'}
                    modelSize={'lg'}
                    isEdit={false}
                    cardHeader={false}
                    handleSubmit={onFormSubmit}
                    saveBtn={isShowBtn}
                    cancelBtn={isShowBtn}
                >
                    {isLoading ? (
                        <div className="bg-light opacity-0.25">
                            <div className="d-flex justify-content-center m-5">
                                <Spinner className="mt-5 mb-5" animation="border" />
                            </div>
                        </div>
                    ) : (
                        <>
                            {approvedLeaveStaffIds.length > 0 && (
                                <Alert variant="warning" className="mb-2">
                                    <FaBan className="me-2" />
                                    {approvedLeaveStaffIds.length} employee(s) on leave
                                </Alert>
                            )}
                            <Table
                                columns={columns}
                                Title={'Employee List'}
                                data={parentList || []}
                                ifComponent={
                                    <div className="d-flex justify-content-end gap-2 my-2">
                                        <Button 
                                            variant="success" 
                                            size="sm" 
                                            onClick={() => handleMarkAll(1)}
                                            disabled={approvedLeaveStaffIds.length > 0}
                                        >
                                            <FaCheckCircle className="me-1" /> Present
                                        </Button>
                                        <Button variant="danger" size="sm" onClick={() => handleMarkAll(0)}>
                                            <FaTimesCircle className="me-1" /> Absent
                                        </Button>
                                        <Button 
                                            variant="primary" 
                                            size="sm" 
                                            onClick={() => handleMarkAll(2)}
                                            disabled={approvedLeaveStaffIds.length > 0}
                                        >
                                            <FaAdjust className="me-1" /> HalfDay
                                        </Button>
                                    </div>
                                }
                                toggle={false}
                                pagination={false}
                            />
                        </>
                    )}
                </ModelViewBox>
            )}
        </React.Fragment>
    );
}

export default Index;